def _parse_decimal(raw: str) -> Decimal:
    match = re.search('-?[0-9][0-9,]*\\.[0-9]{2}', raw)
    if not match: raise ValueError(f"No decimal value found in '{raw}'")
    return Decimal(match.group(0).replace(',', ''))
