def _extract_dbs_rows(tables: list[list[list[str | None]]]) -> list[list[str]]:
    rows: list[list[str]] = []
    for table in tables:
        for row in table:
            if not row or len(row) < 5: continue
            rows.append([cell.strip() if cell else '' for cell in row[:5]]) if row[0] and DBS_DATE_PATTERN.match(row[0].strip()) else None
    return rows
